/* Local sound synthesis: no remote audio or hidden player information. */
(()=>{
 let audio,master,previous,muted=localStorage.getItem('poker-muted')==='true',lastHover=0;
 let countdownId=null,countdownKey='',nextTick=0,tickBeat=0;
 let motionHand=null,motionTimes=new Map();const duration=900;
 const toggle=document.querySelector('#soundToggle');
 function label(){toggle.textContent=muted?'♪̸':'♫';toggle.title=muted?'Enable sounds':'Mute sounds';toggle.setAttribute('aria-label',toggle.title);toggle.setAttribute('aria-pressed',String(muted));}
 function unlock(){try{if(!audio){const C=window.AudioContext||window.webkitAudioContext;if(!C)return;audio=new C();master=audio.createGain();master.gain.value=muted?0:.22;master.connect(audio.destination);}if(audio.state==='suspended')audio.resume().catch(()=>{});}catch{}}
 function tone(freq,length=.08,delay=0,type='sine',volume=.3){if(muted||!audio||audio.state!=='running')return;const time=audio.currentTime+delay,osc=audio.createOscillator(),gain=audio.createGain();osc.type=type;osc.frequency.setValueAtTime(freq,time);gain.gain.setValueAtTime(.001,time);gain.gain.exponentialRampToValueAtTime(volume,time+.006);gain.gain.exponentialRampToValueAtTime(.001,time+length);osc.connect(gain);gain.connect(master);osc.start(time);osc.stop(time+length+.01);}
 function noise(length=.09,delay=0){if(muted||!audio||audio.state!=='running')return;const buffer=audio.createBuffer(1,Math.ceil(audio.sampleRate*length),audio.sampleRate),data=buffer.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=(Math.random()*2-1)*(1-i/data.length);const src=audio.createBufferSource(),filter=audio.createBiquadFilter(),gain=audio.createGain();src.buffer=buffer;filter.type='highpass';filter.frequency.value=1700;gain.gain.value=.13;src.connect(filter);filter.connect(gain);gain.connect(master);src.start(audio.currentTime+delay);}
 function play(name,delay=0){if(name==='hover')tone(1100,.035,delay,'sine',.08);else if(name==='click')tone(650,.045,delay,'triangle',.18);else if(name==='deal'||name==='fold')noise(name==='deal'?.075:.13,delay);else if(name==='check'){tone(330,.05,delay,'triangle');tone(330,.045,delay+.08,'triangle');}else if(name==='call'||name==='raise'){[760,1100,name==='raise'?1450:900].forEach((f,i)=>tone(f,.055,delay+i*.045,'triangle',.17));}else if(name==='join'||name==='bot'){[name==='bot'?520:660,880,1100].forEach((f,i)=>tone(f,.12,delay+i*.07,'sine',.2));}else if(name==='win'){[523,659,784,1046].forEach((f,i)=>tone(f,.22,delay+i*.09,'sine',.22));}else if(name==='turn'){tone(784,.18,delay,'sine',.6);tone(1046,.26,delay+.18,'sine',.6);}else if(name==='time'){tone(660,.15,delay);tone(990,.18,delay+.12);}else if(name==='leave')tone(300,.13,delay,'triangle',.2);}
 document.addEventListener('pointerdown',unlock,{capture:true});document.addEventListener('keydown',unlock,{capture:true});
 document.addEventListener('pointerover',e=>{const b=e.target.closest?.('button');if(!b||b.disabled||b.contains(e.relatedTarget)||performance.now()-lastHover<65)return;lastHover=performance.now();play('hover');});
 document.addEventListener('focusin',e=>{if(e.target.matches?.('button:focus-visible')&&!e.target.disabled)play('hover');});
 document.addEventListener('click',e=>{const b=e.target.closest?.('button');if(b&&!b.disabled&&b!==toggle)play('click');});
 toggle.onclick=()=>{unlock();muted=!muted;localStorage.setItem('poker-muted',String(muted));if(master)master.gain.setTargetAtTime(muted?0:.22,audio.currentTime,.02);label();if(!muted)play('click');};label();
 function animateCards(s,id,old){const now=performance.now();if(motionHand!==s.handNumber){motionHand=s.handNumber;motionTimes=new Map();}
 const fresh=!!old&&s.handNumber!==old.handNumber;const boardBefore=(old?.rabbitBoard?.length?old.rabbitBoard.length:old?.board.length)||0;const self=s.players.find(p=>p.id===id);
 const group=[...document.querySelectorAll('#myCards .card')].map((el,i)=>({el,key:'hand-'+i,newCard:fresh,delay:i*150+150}));
 document.querySelectorAll('#board .card:not(.empty)').forEach((el,i)=>group.push({el,key:'board-'+i,newCard:!!old&&i>=boardBefore,delay:(i-boardBefore)*140}));
 const oldPlayers=new Map((old?.players||[]).map(p=>[p.id,p]));for(const player of s.players){document.querySelectorAll('.seat[data-id="'+player.id+'"] .publicCards .card').forEach((el,i)=>{if(player.cards[i]==='?')return;const key='shown-'+player.id+'-'+i;const before=oldPlayers.get(player.id);if(!motionTimes.has(key))motionTimes.set(key,old&&before?.cards[i]==='?'?now:now-901);const elapsed=now-motionTimes.get(key);if(elapsed>=900)return;el.classList.add('appearingCard');el.style.animationDelay=(-elapsed)+'ms';});if(player.id===id){document.querySelectorAll('#myCards .card').forEach((el,i)=>{if(!((player.shown||0)&(1<<i)))return;const key='myshown-'+i;const before=oldPlayers.get(id);if(!motionTimes.has(key))motionTimes.set(key,old&&!((before?.shown||0)&(1<<i))?now:now-901);const elapsed=now-motionTimes.get(key);if(elapsed>=900)return;el.classList.add('appearingCard');el.style.animationDelay=(-elapsed)+'ms';});}}
 const table=document.querySelector('#table').getBoundingClientRect();for(const item of group){if(!motionTimes.has(item.key))motionTimes.set(item.key,item.newCard?now+item.delay:now-duration-1);const elapsed=now-motionTimes.get(item.key);if(elapsed>=duration||window.matchMedia('(prefers-reduced-motion: reduce)').matches)continue;const box=item.el.getBoundingClientRect();item.el.style.setProperty('--deal-x',(table.x+table.width/2-box.x-box.width/2)+'px');item.el.style.setProperty('--deal-y',(table.y+table.height/2-box.y-box.height/2)+'px');item.el.style.animationDelay=(-elapsed)+'ms';item.el.classList.add('dealing');}
 if(fresh){let n=0;for(let round=0;round<2;round++)for(const p of s.players.filter(p=>p.inHand&&!p.spectating)){if(p.id===id&&!self?.spectating)continue;const avatar=document.querySelector(`.seat[data-id="${p.id}"] .avatar`);if(!avatar)continue;const box=avatar.getBoundingClientRect(),ghost=document.createElement('span');ghost.className='card back dealGhost';ghost.setAttribute('aria-hidden','true');ghost.style.left=table.x+table.width/2+'px';ghost.style.top=table.y+table.height/2+'px';document.body.append(ghost);const delay=n++*100;const a=ghost.animate([{opacity:0,transform:'translate(-50%,-50%) scale(.4) rotate(-15deg)'},{opacity:1,offset:.2},{opacity:1,transform:`translate(${box.x+box.width/2-table.x-table.width/2-20+round*12}px,${box.y-table.y-table.height/2}px) scale(.8) rotate(${round?10:-10}deg)`},{opacity:0}],{duration:650,delay,fill:'both'});a.onfinish=()=>ghost.remove();setTimeout(()=>ghost.remove(),delay+1000);}}
 }
 setInterval(()=>{const s=previous,p=s?.players[s.turn];const remaining=(s?.deadline||0)-Date.now();if(!s||!countdownId||p?.id!==countdownId||p.folded||p.spectating||s.runningOut||s.street==='showdown'||remaining<=0||document.hidden||muted){nextTick=0;return;}const key=[s.code,s.handNumber,s.street,s.turn,s.deadline].join(':');if(key!==countdownKey){countdownKey=key;nextTick=0;tickBeat=0;}const now=performance.now();if(now<nextTick)return;const gap=remaining<=2000?150:remaining<=5000?250:remaining<=10000?500:1000;nextTick=now+gap;tone(tickBeat++%2?1450:1150,.032,0,'triangle',remaining<=5000?.25:.16);},40);
 window.pokerEffects={stopCountdown(){countdownId=null;nextTick=0;},tick(){play('hover');},update(s,id){countdownId=id;const old=previous;if(old&&old.code===s.code){const before=new Map(old.players.map(p=>[p.id,p]));for(const p of s.players){const prev=before.get(p.id);if(!prev&&!p.kicked)play(p.bot?'bot':'join');if(prev&&!prev.kicked&&p.kicked)play('leave');if(prev&&p.stats.actions>prev.stats.actions)play(p.action?.startsWith('Raise')?'raise':p.action);if(prev&&p.timeCards<prev.timeCards)play('time');}if(s.handNumber!==old.handNumber){for(let i=0;i<Math.min(s.players.filter(p=>p.inHand).length*2,16);i++)play('deal',i*.1);}else if(s.board.length>old.board.length){for(let i=0;i<s.board.length-old.board.length;i++)play('deal',i*.14);}if(s.rabbitBoard?.length&&!old.rabbitBoard?.length){for(let i=0;i<s.rabbitBoard.length-s.board.length;i++)play('deal',i*.14);}if(s.street==='showdown'&&old.street!=='showdown')play('win');if((s.turn!==old.turn||s.street!==old.street||s.handNumber!==old.handNumber)&&s.players[s.turn]?.id===id&&!s.runningOut&&s.street!=='showdown')play('turn');}animateCards(s,id,old?.code===s.code?old:null);previous=s;}};
})();
